	/** 
	 * jumpstart the process by instantiating2 Appointment
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		appointmentId = AppointmentService.getAppointmentInstance()
		.createAppointment( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AppointmentService.getAppointmentInstance()
				.createAppointment( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.appointmentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Appointment : " + successValue.getAppointmentId());
							  if (successValue.getAppointmentId().equals(appointmentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAppointmentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Appointment test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on appointment consumed")
					);
			subscriber.appointmentSubscribe( appointmentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Appointment : " + successValue.getAppointmentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAppointmentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on appointment for appointmentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Appointment. 
	 */
	protected Appointment read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Appointment" );

		Appointment entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Appointment with primary key" );
		msg.append( appointmentId );
		
		AppointmentFetchOneSummary fetchOneSummary = new AppointmentFetchOneSummary( appointmentId );

		try {
			entity = AppointmentService.getAppointmentInstance().getAppointment( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Appointment " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Appointment.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Appointment." );

		StringBuilder msg = new StringBuilder( "Failed to update a Appointment : " );        
		Appointment entity = read();
		UpdateAppointmentCommand command = generateUpdateCommand();
		command.setAppointmentId(entity.getAppointmentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Appointment." );

			// for use later on...
			appointmentId = entity.getAppointmentId();

			AppointmentService proxy = AppointmentService.getAppointmentInstance();  

			proxy.updateAppointment( command ).get();

			LOGGER.info( "-- Successfully saved Appointment - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + appointmentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Appointment.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Appointment." );

		Appointment entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Appointment with id " + appointmentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Appointment with id " + appointmentId );

			throw e;
		}

		try{
			AppointmentService.getAppointmentInstance().delete( new DeleteAppointmentCommand( entity.getAppointmentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Appointment with id " + appointmentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Appointment with id " + appointmentId );

			throw e;
		}
	}

	/**
	 * get all Appointments.
	 */
	protected List<Appointment> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Appointments:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Appointment : " );        
		List<Appointment> collection  = new ArrayList<>();

		try {
			// call the static get method on the AppointmentService
			collection = AppointmentService.getAppointmentInstance().getAllAppointment();
			assertNotNull( collection, "An Empty collection of Appointment was incorrectly returned.");
			
			// Now print out the values
			Appointment entity = null;            
			Iterator<Appointment> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAppointmentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

